WITH valid AS (SELECT id, order_id, product_id, unit_price, CASE WHEN unit_price >= 420 THEN 'High' WHEN unit_price >= 160 THEN 'Medium' ELSE 'Low' END AS unit_price_level FROM order_items WHERE product_id IS NOT NULL AND order_id IN (15, 17)) SELECT id, product_id, unit_price_level, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY unit_price, id) AS seq_no, NTILE(10) OVER (PARTITION BY order_id ORDER BY unit_price, id) AS unit_price_bucket FROM valid
